+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.EnumSet;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/** The filters supported by the customer list. */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = statuses == null || statuses.isEmpty()
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public static CustomerFilter empty() {
+        return new CustomerFilter("", Set.of());
+    }
+
+    /** Returns whether this filter matches the supplied customer. */
+    public boolean matches(Customer customer) {
+        if (!matchesName(customer)) {
+            return false;
+        }
+        return statuses.isEmpty() || statuses.contains(customer.status());
+    }
+
+    /** Whitespace-only input is an empty filter for URL and query purposes. */
+    public boolean hasName() {
+        return !name.isBlank();
+    }
+
+    private boolean matchesName(Customer customer) {
+        if (!hasName()) {
+            return true;
+        }
+
+        String firstName = fold(customer.firstName());
+        String lastName = fold(customer.lastName());
+        return java.util.Arrays.stream(name.strip().split("\\s+"))
+                        .map(CustomerFilter::fold)
+                        .allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+
+    /** Case- and accent-insensitive representation used by both sides of a comparison. */
+    public static String fold(String value) {
+        String decomposed = Normalizer.normalize(value, Normalizer.Form.NFD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
